const listNotificationsPage = `-- name: ListNotificationsPage :many
SELECT id, owner_user_id, project_id, kind, severity, origin, title, body,
       target_kind, target_id, app_id, app_installation_id, source_process,
       source_id, source_digest, created_at, read_at, read_change_sequence, created_change_sequence
FROM workos_core.notifications
WHERE owner_user_id = $1
  AND ($2 ::uuid IS NULL OR project_id = $2 ::uuid)
  AND (NOT $3 OR read_at IS NULL)
  AND ($4 ::text IS NULL OR kind = $4 ::text)
  AND ($5 ::text IS NULL
       OR position($5 ::text IN lower(title)) > 0)
  AND ($6 ::timestamptz IS NULL
       OR (created_at, id) < ($6 ::timestamptz, $7 ::uuid))
ORDER BY created_at DESC, id DESC
LIMIT $8
`

type ListNotificationsPageParams struct {
	OwnerUserID   string
	ProjectID     pgtype.UUID
	UnreadOnly    interface{}
	Kind          pgtype.Text
	TitleNeedle   pgtype.Text
	CursorCreated *time.Time
	CursorID      pgtype.UUID
	RowLimit      int32
}

func (q *Queries) ListNotificationsPage(ctx context.Context, arg ListNotificationsPageParams) ([]WorkosCoreNotification, error) {
	rows, err := q.db.Query(ctx, listNotificationsPage,
		arg.OwnerUserID,
		arg.ProjectID,
		arg.UnreadOnly,
		arg.Kind,
		arg.TitleNeedle,
		arg.CursorCreated,
		arg.CursorID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []WorkosCoreNotification
	for rows.Next() {
		var i WorkosCoreNotification
		if err := rows.Scan(
			&i.ID,
			&i.OwnerUserID,
			&i.ProjectID,
			&i.Kind,
			&i.Severity,
			&i.Origin,
			&i.Title,
			&i.Body,
			&i.TargetKind,
			&i.TargetID,
			&i.AppID,
			&i.AppInstallationID,
			&i.SourceProcess,
			&i.SourceID,
			&i.SourceDigest,
			&i.CreatedAt,
			&i.ReadAt,
			&i.ReadChangeSequence,
			&i.CreatedChangeSequence,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

