const selectSweepableNotifications = `-- name: SelectSweepableNotifications :many
SELECT id, owner_user_id FROM workos_core.notifications
WHERE read_at IS NOT NULL AND read_at < $1
ORDER BY read_at, id
LIMIT $2
`

type SelectSweepableNotificationsParams struct {
	Cutoff   *time.Time
	MaxBatch int32
}

type SelectSweepableNotificationsRow struct {
	ID          string
	OwnerUserID string
}

// Bounded sweep: only already-read notifications older than the cutoff are
// candidates. Recent unread facts are never swept.
func (q *Queries) SelectSweepableNotifications(ctx context.Context, arg SelectSweepableNotificationsParams) ([]SelectSweepableNotificationsRow, error) {
	rows, err := q.db.Query(ctx, selectSweepableNotifications, arg.Cutoff, arg.MaxBatch)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SelectSweepableNotificationsRow
	for rows.Next() {
		var i SelectSweepableNotificationsRow
		if err := rows.Scan(&i.ID, &i.OwnerUserID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

